const settlementIndex=new Map(),geoCache=new Map();
function cleanSettlementName(s){return geoNorm(s).replace(/\s+(küla|alevik|alev|linn|asundus)(?=\s*\/|$)/g,'').replace(/\s*\/\s*/g,'/')}
for(const [id,label,county,municipality,lat,lon] of settlementRows){const record={id,label,county,municipality,coords:[lat,lon]};for(const name of cleanSettlementName(label).split('/')){const key=geoNorm(name);if(!settlementIndex.has(key))settlementIndex.set(key,[]);settlementIndex.get(key).push(record)}}
const countyVariants={'harjumaa':['harju county','harju maakond'],'hiiumaa':['hiiu county','hiiu maakond'],'ida-virumaa':['ida-viru county','ida-viru maakond'],'järvamaa':['järva county','järva maakond'],'jõgevamaa':['jõgeva county','jõgeva maakond'],'läänemaa':['lääne county','lääne maakond'],'lääne-virumaa':['lääne-viru county','lääne-viru maakond'],'pärnumaa':['pärnu county','pärnu maakond'],'põlvamaa':['põlva county','põlva maakond'],'raplamaa':['rapla county','rapla maakond'],'saaremaa':['saare county','saare maakond'],'tartumaa':['tartu county','tartu maakond'],'valgamaa':['valga county','valga maakond'],'viljandimaa':['viljandi county','viljandi maakond'],'võrumaa':['võru county','võru maakond']};
function countyInText(county,text){return [geoNorm(county),...(countyVariants[geoNorm(county)]||[])].some(v=>text.includes(v))}
function placeTokens(text){const words=[...text.matchAll(/[\p{L}\d]+(?:-[\p{L}\d]+)*/gu)];let found=[];for(let i=0;i<words.length;i++)for(let size=1;size<=4&&i+size<=words.length;size++){const key=words.slice(i,i+size).map(w=>w[0]).join(' ');const variants=[key,key.replace(/(?:sse|s|le|l)$/u,'')];for(const v of variants){const candidates=settlementIndex.get(v);if(candidates)found.push({key:v,index:words[i].index,records:candidates,exact:key===v})}}return found}
function fallbackMatch(norm){const matches=[];for(const key of geoKeys){const escaped=key.replace(/[.*+?^{}()|[\]\\$]/g,'\\$&');const re=new RegExp('(^|[^\\p{L}])('+escaped+')(?=$|[^\\p{L}]|(?:s|sse|l|le)(?=$|[^\\p{L}]))','u');const m=re.exec(norm);if(m)matches.push({key,index:m.index,wide:broadPlace(key)})}matches.sort((a,b)=>Number(a.wide)-Number(b.wide)||a.index-b.index||b.key.length-a.key.length);if(!matches.length)return null;const m=matches[0];return{coords:places[m.key],name:m.key,wide:true,manual:false,status:'region',label:'Ajalooline nimi või ligikaudne piirkond'}}
function editDistance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next}return row[b.length]}
function suggestedPlaces(norm){const target=cleanSettlementName(norm.split(/[,;/()]/)[0]).replace(/\s+(mõisavald|vald|khk|v)$/u,'').trim();if(target.length<4)return[];const max=target.length>=7?2:1;let hits=[];for(const[key,rs]of settlementIndex){if(Math.abs(key.length-target.length)>max)continue;const distance=editDistance(target,key);if(distance>0&&distance<=max)for(const r of rs)hits.push({...r,distance})}hits.sort((a,b)=>a.distance-b.distance||Number(countyInText(b.county,norm))-Number(countyInText(a.county,norm)));return hits.slice(0,8)}
function placeMatch(place){const norm=geoNorm(place);if(!norm)return{status:'missing',coords:null,name:'Sünnikoht puudub',candidates:[]};if(geoOverrides.has(norm)){const value=geoOverrides.get(norm);return{coords:Array.isArray(value)?value:value.coords,name:Array.isArray(value)?'Kasutaja määratud koht':value.label,manual:true,status:'confirmed',candidates:[]}}if(geoCache.has(norm))return geoCache.get(norm);let result;const tokens=placeTokens(norm).filter(t=>{const tail=norm.slice(t.index+t.key.length);return !/^\s*(county|maakond|vald|v\b)/u.test(tail)&&(!broadPlace(t.key)||/^\s*küla/u.test(tail))}).sort((a,b)=>a.index-b.index||b.key.length-a.key.length||Number(b.exact)-Number(a.exact));if(tokens.length){const first=tokens[0];const suffix=norm.slice(first.index+first.key.length);if(/^\s*(khk|kihelkond)\b/u.test(suffix)){result=fallbackMatch(norm)||{status:'unknown',coords:null,name:'Koht tuvastamata',candidates:[]}}else{let candidates=[...new Map(first.records.map(r=>[r.id,r])).values()];const counties=candidates.filter(r=>countyInText(r.county,norm));if(counties.length)candidates=counties;const municipalities=candidates.filter(r=>r.municipality&&norm.includes(geoNorm(r.municipality).replace(/\s+vald$/,''))&&geoNorm(r.municipality).replace(/\s+vald$/,'')!==first.key);if(municipalities.length)candidates=municipalities;const typed=candidates.filter(r=>norm.includes(geoNorm(r.label.split('/')[0]).trim()));if(typed.length)candidates=typed;if(candidates.length===1){const r=candidates[0];result={coords:r.coords,name:[r.label,r.county,r.municipality].filter(Boolean).join(', '),manual:false,wide:false,status:'settlement',candidates:[],record:r}}else result={coords:null,name:'Mitu võimalikku asulat',status:'ambiguous',candidates}}}else{result=fallbackMatch(norm);if(!result)result={coords:null,name:'Koht tuvastamata',status:'unknown',candidates:suggestedPlaces(norm)}}geoCache.set(norm,result);return result}
function locate(place){return placeMatch(place).coords||null}
function setPlaceCorrection(place,coords,label){geoOverrides.set(geoNorm(place),{coords,label});geoCache.delete(geoNorm(place))}
function correctionDocument(){return{format:'sugupuu-places',version:1,places:[...geoOverrides].map(([place,v])=>({place,lat:(Array.isArray(v)?v:v.coords)[0],lon:(Array.isArray(v)?v:v.coords)[1],label:Array.isArray(v)?'Kasutaja määratud koht':v.label}))}}
function importPlaceCorrections(data){if(!data||data.format!=='sugupuu-places'||data.version!==1||!Array.isArray(data.places)||data.places.length>5000)throw Error('See ei ole toetatud kohaparanduste fail.');const rows=data.places.map(p=>{if(!p||typeof p.place!=='string'||!p.place.trim()||p.place.length>1000||typeof p.label!=='string'||!p.label.trim()||p.label.length>1000||!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||p.lat<57||p.lat>60.5||p.lon<21||p.lon>29)throw Error('Failis on vigane kohaparandus. Ühtegi parandust ei lisatud.');return p});for(const p of rows)setPlaceCorrection(p.place,[p.lat,p.lon],p.label);return rows.length}

function render(){const svg=$('view'),q=$('search').value.toLocaleLowerCase('et');$('treeTab').classList.toggle('active',mode==='tree');$('mapTab').classList.toggle('active',mode==='map');svg.setAttribute('viewBox','0 0 900 490');let html='';if(mode==='tree'){const root=$('root').value||people[0]?.id,levels=[[root]],seen=new Set([root]);const depthLimit=Number($('treeDepth').value||5)||people.length;let treeTruncated=false;for(let g=1;g<depthLimit;g++){let next=[...new Set(levels[g-1].flatMap(parents))].filter(id=>!seen.has(id));if(!next.length)break;const remaining=2000-seen.size;if(remaining<=0){treeTruncated=true;break}if(next.length>remaining){next=next.slice(0,remaining);treeTruncated=true}next.forEach(id=>seen.add(id));levels.push(next);if(treeTruncated)break}const pos=new Map;levels.forEach((ids,g)=>ids.forEach((id,i)=>pos.set(id,[450+(i-(ids.length-1)/2)*Math.max(135,760/Math.max(ids.length,1)),(levels.length-1-g)*100+55])));let minX=Math.min(...[...pos.values()].map(p=>p[0]))-70,maxX=Math.max(...[...pos.values()].map(p=>p[0]))+70;const treeWidth=Math.max(900,maxX-minX+30),treeHeight=Math.max(490,levels.length*100+10);svg.setAttribute('viewBox',`${Math.min(0,minX)} 0 ${treeWidth} ${treeHeight}`);svg.style.minWidth=treeWidth+'px';svg.style.height=treeHeight+'px';$('treeDepth').disabled=false;for(const[id,[x,y]]of pos)for(const parent of parents(id)){if(!pos.has(parent))continue;const[px,py]=pos.get(parent);html+=`<path class="link" data-child="${esc(id)}" data-parent="${esc(parent)}" d="M${x},${y-29} C${x},${(y+py)/2} ${px},${(y+py)/2} ${px},${py+29}" stroke-linecap="round"><title>${esc(person(parent).name)} → ${esc(person(id).name)}</title></path>`}for(const[id,[x,y]]of pos){const p=person(id),dim=q&&!p.name.toLocaleLowerCase('et').includes(q);html+=`<g class="person" data-id="${esc(id)}" tabindex="0" role="button" aria-label="${esc(p.name)}" opacity="${dim?.2:1}" transform="translate(${x},${y})"><rect x="-64" y="-29" width="128" height="58" rx="8" fill="${id===root?'#dbe7ba':'#fffefa'}" stroke="#cad5bf"/><text text-anchor="middle" y="-3" fill="#263f37" font-family="Georgia" font-size="13">${esc(p.name.length>19?p.name.slice(0,18)+'…':p.name)}</text><text text-anchor="middle" y="16" fill="#7b8575" font-size="10">${esc(p.birth||'Sünniaeg teadmata')}</text></g>`}$('legend').textContent=`Lähteisik + ${levels.length-1} põlvkonda tagasi · ${pos.size} inimest. Suurt puud saad kerida külgedele ja üles-alla.${treeTruncated?' Kuvatud on kuni 2000 inimest; vali lähteisikuks mõne haru esivanem.':''}`;$('status').textContent=q?`${people.filter(p=>p.name.toLocaleLowerCase('et').includes(q)).length} nimevastet kogu failis. Teised harud avad lähteisiku valikust.`:'';}else{svg.style.minWidth='0';svg.style.height='490px';$('treeDepth').disabled=true;const xy=(lat,lon)=>[(lon-21.5)*110+75,(59.8-lat)*175+30];if(mapData){for(const ring of mapData.land||[])html+=`<path d="${ring.map(([lon,lat],i)=>(i?'L':'M')+xy(lat,lon).join(',')).join(' ')}Z" fill="#e4ead8" stroke="#c2ceb5"/>`;for(const ring of mapData.lakes||[])html+=`<path d="${ring.map(([lon,lat],i)=>(i?'L':'M')+xy(lat,lon).join(',')).join(' ')}Z" fill="#f6f8ef"/>`}for(const name of ['Tallinn','Tartu','Pärnu','Kuressaare','Narva']){const ref=places[geoNorm(name)];if(!ref)continue;const [x,y]=xy(...ref);html+=`<text x="${x+8}" y="${y-8}" fill="#929d87" font-size="11">${name}</text>`}const unknown=[],groups=new Map;for(const p of people){const loc=locate(p.place);if(!loc){unknown.push(p);continue}if(q&&!p.name.toLocaleLowerCase('et').includes(q))continue;const key=loc.join(',');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)}for(const[key,ps]of groups){const base=xy(...key.split(',').map(Number));ps.forEach((p,i)=>{const a=i*2.4,r=ps.length>1?6+5*Math.sqrt(i):0,x=base[0]+Math.cos(a)*r,y=base[1]+Math.sin(a)*r;html+=`<g class="person" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(p.name)}"><title>${esc(p.name+' · '+p.place)}</title><circle cx="${x}" cy="${y}" r="6" fill="${p.id===selected?'#bd7840':'#607e43'}" stroke="white" stroke-width="2"/></g>`})}$('legend').textContent='Kohanimede ligikaudsed keskpunktid · piirkonnanime vaste võib olla ebatäpne · kattuvad punktid on nihutatud.';$('status').textContent=`${people.length-unknown.length}/${people.length} inimest kaardil. ${unknown.length?'Sünnikoht puudub või ei ole sõnastikus: '+[...new Set(unknown.map(p=>p.place||'teadmata'))].join('; '):''}`;if(unknown.length){$('status').innerHTML='<strong>'+String(people.length-unknown.length)+'/'+people.length+' inimest kaardil.</strong> '+unknown.length+' inimesel sünnikoht puudub või on tuvastamata. Vali nimi, et näha põhjust või määrata koordinaadid: '+unknown.map(p=>'<button class="missing-person" data-missing="'+esc(p.id)+'">'+esc(p.name)+' · '+esc(p.place||'Sünnikoht puudub')+'</button>').join(' ');$('status').querySelectorAll('[data-missing]').forEach(b=>b.onclick=()=>detail(b.dataset.missing))}}svg.innerHTML=html;if(mode==='tree'){$('graphScroll').scrollTop=$('graphScroll').scrollHeight;$('graphScroll').scrollLeft=Math.max(0,($('graphScroll').scrollWidth-$('graphScroll').clientWidth)/2)}svg.querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>detail(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(el.dataset.id)}}})}
async function unzipGed(buffer){const d=new DataView(buffer);let eoc=-1;for(let i=d.byteLength-22;i>=Math.max(0,d.byteLength-65557);i--)if(d.getUint32(i,true)===0x06054b50){eoc=i;break}if(eoc<0)throw Error('ZIP-faili ei saa lugeda. Proovi lahtipakitud .ged-faili.');const entries=d.getUint16(eoc+10,true);let off=d.getUint32(eoc+16,true),found=[];for(let i=0;i<entries;i++){if(d.getUint32(off,true)!==0x02014b50)throw Error('Vigane ZIP.');const flags=d.getUint16(off+8,true),method=d.getUint16(off+10,true),size=d.getUint32(off+20,true),raw=d.getUint32(off+24,true),nl=d.getUint16(off+28,true),xl=d.getUint16(off+30,true),cl=d.getUint16(off+32,true),local=d.getUint32(off+42,true),name=new TextDecoder().decode(new Uint8Array(buffer,off+46,nl));if(/\.(ged|gedcom)$/i.test(name))found.push({flags,method,size,raw,local});off+=46+nl+xl+cl}if(found.length!==1)throw Error('ZIP peab sisaldama täpselt ühte .ged või .gedcom faili.');const f=found[0];if(f.flags&1)throw Error('Parooliga ZIP pole toetatud.');if(f.raw>10*1024*1024)throw Error('GEDCOM-faili ülempiir on 10 MB.');const start=f.local+30+d.getUint16(f.local+26,true)+d.getUint16(f.local+28,true);const bytes=new Uint8Array(buffer,start,f.size);if(f.method===0)return new TextDecoder().decode(bytes);if(f.method!==8)throw Error('See ZIP-tihendus pole toetatud. Laadi .ged-fail.');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));const reader=stream.getReader();let chunks=[],length=0;while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>10*1024*1024){await reader.cancel();throw Error('Lahtipakitud fail ületab 10 MB.')}chunks.push(value)}return new Blob(chunks).text()}
$('load').onclick=$('loadTop').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Faili ülempiir on 10 MB.');$('status').textContent='Loen sugupuud…';const txt=/\.zip$/i.test(f.name)?await unzipGed(await f.arrayBuffer()):await f.text();if(!/^0 HEAD/m.test(txt.replace(/^\uFEFF/,'')))throw Error('Valitud fail ei ole toetatud GEDCOM-eksport.');const data=parseGed(txt);setData(data,'Minu sugupuu');source='upload'}catch(err){$('status').textContent=err.message}finally{e.target.value=''}};$('demo').onclick=()=>{source='demo';setData(parseGed(demoText),'Näidispere · väljamõeldud andmed')};$('treeDepth').onchange=render;$('root').onchange=()=>{render();detail($('root').value)};$('search').oninput=render;$('treeTab').onclick=()=>{mode='tree';render()};$('mapTab').onclick=()=>{mode='map';render()};$('reset').onclick=()=>{$('search').value='';$('root').selectedIndex=0;render();detail($('root').value)};setData(parseGed(demoText),'Näidispere · väljamõeldud andmed');

function printLines(text,max=24){const words=String(text).split(/\s+/).flatMap(w=>w.length>max?w.match(new RegExp('.{1,'+max+'}','g')):[w]);let lines=[''];for(const w of words){const i=lines.length-1;if(lines[i]&&(lines[i]+' '+w).length>max)lines.push(w);else lines[i]+=(lines[i]?' ':'')+w}return lines}
function buildPrint(){const rootId=$('root').value||people[0]?.id,rootPerson=person(rootId);if(!rootPerson)return;const maxDepth=+$('printGenerations').value-1;let nodes=[],edges=[],leaf=0;function walk(id,g,path){const p=person(id);if(!p||path.has(id))return null;const n={p,g,x:0,index:nodes.length};nodes.push(n);const nextPath=new Set(path);nextPath.add(id);const pars=g<maxDepth?parents(id):[];const children=pars.map(pid=>walk(pid,g+1,nextPath)).filter(Boolean);if(children.length){n.x=children.reduce((s,c)=>s+c.x,0)/children.length;children.forEach(c=>edges.push([n,c]))}else n.x=leaf++*250+125;return n}walk(rootId,0,new Set());const depth=Math.max(...nodes.map(n=>n.g));const rowHeight=Math.max(145,...nodes.map(n=>printLines(n.p.name).length*23+65));const width=Math.max(550,leaf*250),height=(depth+1)*rowHeight+30;const y=n=>(depth-n.g)*rowHeight+rowHeight/2;let svg='';for(const[a,b]of edges){const mid=(y(a)+y(b))/2;svg+='<path d="M'+a.x+','+(y(a)-48)+' C'+a.x+','+mid+' '+b.x+','+mid+' '+b.x+','+(y(b)+48)+'" fill="none" stroke="#a5b29a" stroke-width="2"/>'}for(const n of nodes){const lines=printLines(n.p.name);const boxHeight=Math.max(96,lines.length*23+54);svg+='<g transform="translate('+n.x+','+y(n)+')"><rect x="-114" y="'+(-boxHeight/2)+'" width="228" height="'+boxHeight+'" rx="8" fill="'+(n.g===0?'#e6ecd8':'#fffefa')+'" stroke="#bbc7ae" stroke-width="1.6"/>';lines.forEach((line,i)=>svg+='<text text-anchor="middle" y="'+(-(lines.length-1)*11.5+i*23-9)+'" font-family="Georgia,serif" font-size="20" fill="#263d36">'+esc(line)+'</text>');svg+='<text text-anchor="middle" y="'+(lines.length*11.5+17)+'" font-family="system-ui,sans-serif" font-size="15" fill="#6c7864">'+esc(n.p.birth||'Sünniaeg teadmata')+'</text></g>'}
$('printSheet').innerHTML='<div class="print-kicker">PEREKONNALUGU · ESIVANEMAD</div><h1>'+esc(rootPerson.name)+' sugupuu</h1><div class="print-subtitle">'+(depth+1)+' põlvkonda · '+new Set(nodes.map(n=>n.p.id)).size+' inimest · '+(source==='demo'?'Väljamõeldud näidispere':'Koostatud sinu GEDCOM-ekspordist')+'</div><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Prinditav esivanemate sugupuu">'+svg+'</svg><div class="print-footer"><span>Sugupuu · sugulusseosed ekspordifaili järgi</span><span>'+new Date().toLocaleDateString('et-EE')+' · '+(nodes.length>new Set(nodes.map(n=>n.p.id)).size?'Korduv esivanem on näidatud igas harus.':'Puuduvad andmed on jäetud täitmata.')+'</span></div>';
let pageStyle=$('printPageStyle');if(!pageStyle){pageStyle=document.createElement('style');pageStyle.id='printPageStyle';document.head.append(pageStyle)}pageStyle.textContent='@media print{@page{size:'+$('printPaper').value+' landscape;margin:12mm}#printSheet svg{max-height:'+($('printPaper').value==='A4'?'140':'210')+'mm}}'}
$('printOpen').onclick=()=>{buildPrint();$('printDialog').hidden=false;document.body.classList.add('printing');$('printClose').focus()};$('printClose').onclick=()=>{$('printDialog').hidden=true;document.body.classList.remove('printing');$('printOpen').focus()};$('printGenerations').onchange=$('printPaper').onchange=buildPrint;$('printNow').onclick=()=>window.print();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('printDialog').hidden)$('printClose').click()});

function geoCandidateLabel(r){return [r.label,r.county,r.municipality].filter(Boolean).join(' · ')}
function showGeoDetail(p){const info=placeMatch(p.place),labels={settlement:'Asula leitud',region:'Ainult piirkond või ajalooline vaste',ambiguous:'Mitu võimalikku vastet',unknown:'Koht tuvastamata',missing:'Sünnikoht puudub',confirmed:'Kasutaja kinnitatud'};$('geoDetail').innerHTML='<h4>Sünnikoht kaardil</h4><span class="geo-badge geo-'+info.status+'">'+labels[info.status]+'</span><p>'+esc(info.coords?info.name+'. Ligikaudne asukoht, mitte täpne sünniaadress.':(info.status==='ambiguous'?'Sama nimega asulaid on mitu. Vali õige koht; enne kinnitamist punkti ei näidata.':'Koht vajab täpsustamist. Võid otsida asulat või sisestada koordinaadid.'))+'</p>'+(info.coords?'<button id="showOnMap">Näita kaardil</button>':'')+'<div id="geoCandidates"></div><label>Otsi asulat<input id="geoLookup" type="search" placeholder="Asula nimi"></label><div id="geoLookupResults"></div><p class="geo-source">EKI asulaloend: 15.02.2010. Maakonnad ja vallad on tolleaegsed. Kohanimede allikaid vaata lehe juhendist.</p><details><summary>Määra koordinaadid käsitsi</summary><p>Parandus kehtib sama kohatekstiga inimestele. Säilitamiseks salvesta all kohaparanduste fail.</p><label>Laiuskraad <input id="geoLat" type="number" step="any" placeholder="58.378" value="'+(info.coords?.[0]??'')+'"></label><label>Pikkuskraad <input id="geoLon" type="number" step="any" placeholder="26.729" value="'+(info.coords?.[1]??'')+'"></label><button id="geoSave">Rakenda kohale</button></details><button id="geoClear">Eemalda kohaparandus</button><p id="geoError" role="status"></p>';
function candidates(target,rows,caption){$(target).innerHTML=(rows.length?'<p>'+caption+'</p>':'')+rows.map((r,i)=>'<button class="geo-candidate" data-choice="'+i+'">'+esc(geoCandidateLabel(r))+'</button>').join('');$(target).querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(!p.place.trim()){$('geoError').textContent='Sünnikoht puudub. Lisa see esmalt sugupuu lähteandmetesse.';return}const r=rows[+b.dataset.choice];setPlaceCorrection(p.place,r.coords,geoCandidateLabel(r));render();detail(p.id);updateCorrectionsStatus()})}
candidates('geoCandidates',info.candidates||[],info.status==='ambiguous'?'Vali õige asula:':'Kas mõtlesid mõnda neist?');
$('geoLookup').oninput=()=>{const q=geoNorm($('geoLookup').value);if(q.length<2){$('geoLookupResults').innerHTML='';return}const rows=settlementRows.filter(r=>geoNorm(r[1]+' '+r[2]+' '+r[3]).includes(q)).slice(0,15).map(([id,label,county,municipality,lat,lon])=>({id,label,county,municipality,coords:[lat,lon]}));candidates('geoLookupResults',rows,rows.length?'Asulad (kuni 15 vastet):':'');if(!rows.length)$('geoLookupResults').textContent='Vasteid ei leitud.'};
if(info.coords)$('showOnMap').onclick=()=>{mode='map';$('search').value=p.name;render();detail(p.id)};
$('geoSave').onclick=()=>{const lat=Number($('geoLat').value),lon=Number($('geoLon').value);if(!p.place.trim()){$('geoError').textContent='Sünnikoht puudub failis. Lisa see esmalt oma sugupuu lähteandmetesse.';return}if(!$('geoLat').value||!$('geoLon').value||!Number.isFinite(lat)||!Number.isFinite(lon)||lat<57||lat>60.5||lon<21||lon>29){$('geoError').textContent='Sisesta Eesti ja lähialade koordinaadid: laius 57–60,5 ja pikkus 21–29.';return}setPlaceCorrection(p.place,[lat,lon],'Käsitsi määratud asukoht');render();detail(p.id);updateCorrectionsStatus()};
$('geoClear').onclick=()=>{geoOverrides.delete(geoNorm(p.place));geoCache.delete(geoNorm(p.place));render();detail(p.id);updateCorrectionsStatus()}}
function updateCorrectionsStatus(message){$('correctionStatus').textContent=message||geoOverrides.size+' kohaparandust selles seansis. Faili salvestamine säilitab need sinu arvutis.'}
$('exportCorrections').onclick=()=>{if(!geoOverrides.size){updateCorrectionsStatus('Salvestamiseks kinnita või paranda esmalt vähemalt üks koht.');return}const blob=new Blob([JSON.stringify(correctionDocument(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sugupuu-kohaparandused.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);updateCorrectionsStatus('Kohaparanduste fail on allalaadimiseks valmis. See sisaldab kohanimesid ja koordinaate, mitte inimeste nimesid.')};
$('importCorrections').onclick=()=>$('correctionFile').click();
$('correctionFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Paranduste faili ülempiir on 2 MB.');const count=importPlaceCorrections(JSON.parse(await f.text()));render();detail(selected);updateCorrectionsStatus('Laaditud '+count+' kohaparandust. Kokku '+geoOverrides.size+'.')}catch(err){updateCorrectionsStatus(err instanceof SyntaxError?'Fail ei ole korrektne JSON.':err.message)}finally{e.target.value=''}};
updateCorrectionsStatus();
